def solve_per_cell(g):
    g=[row[:] for row in g]; H,W=len(g),len(g[0])
    cnt=collections.Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    others=[c for c,n in cnt.most_common() if c!=bg]
    barc=max(others,key=lambda c:sum(row.count(c) for row in g))
    mkc=min(others,key=lambda c:sum(row.count(c) for row in g))
    seen=[[False]*W for _ in range(H)]; bars=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==barc and not seen[r][c]:
                st=[(r,c)];seen[r][c]=True;cells=[]
                while st:
                    y,x=st.pop();cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==barc and not seen[ny][nx]:
                            seen[ny][nx]=True;st.append((ny,nx))
                bars.append(cells)
    out=[row[:] for row in g]
    for cells in bars:
        ys=[y for y,_ in cells]; xs=[x for _,x in cells]
        vert = len(set(ys))>1 and len(set(xs))==1
        dirs=((0,1),(0,-1)) if vert else ((1,0),(-1,0))
        for (y,x) in cells:
            for dy,dx in dirs:
                cy,cx=y+dy,x+dx
                while 0<=cy<H and 0<=cx<W:
                    v=g[cy][cx]
                    if v==mkc:
                        out[cy][cx]=4; break
                    if v==barc: break
                    out[cy][cx]=mkc; cy+=dy; cx+=dx
    return out
